import api from "../api/axios";

/**
 * Helper to download binary files (Excel / PDF) generated by IntraSphere backend.
 */
export async function downloadReport({ endpoint, format = "excel", params = {}, defaultFilename = "report" }) {
  try {
    const ext = format === "pdf" ? "pdf" : "xlsx";
    const mimeType = format === "pdf"
      ? "application/pdf"
      : "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

    const response = await api.get(endpoint, {
      params: { ...params, format },
      responseType: "blob",
    });

    // Check if response is actually JSON error blob
    if (response.data.type === "application/json") {
      const text = await response.data.text();
      const err = JSON.parse(text);
      throw new Error(err.detail || "Export failed");
    }

    // Try extracting filename from Content-Disposition header
    let filename = `${defaultFilename}.${ext}`;
    const disposition = response.headers["content-disposition"];
    if (disposition && disposition.indexOf("filename=") !== -1) {
      const matches = disposition.match(/filename=["']?([^"';]+)["']?/);
      if (matches && matches[1]) {
        filename = matches[1];
      }
    }

    const blob = new Blob([response.data], { type: mimeType });
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    link.remove();
    window.URL.revokeObjectURL(url);

    return { success: true, filename };
  } catch (error) {
    if (error.response && error.response.data instanceof Blob) {
      try {
        const text = await error.response.data.text();
        const json = JSON.parse(text);
        if (json.detail) {
          error.message = json.detail;
        }
      } catch (_) {}
    }
    console.error("Failed to download report:", error);
    throw error;
  }
}

/**
 * HR Administrator: Export Attendance and Punctuality Reports
 */
export async function exportAttendanceReport({ format = "excel", startDate, endDate, department, search }) {
  return downloadReport({
    endpoint: "/api/v1/reports/attendance/export",
    format,
    params: {
      start_date: startDate || undefined,
      end_date: endDate || undefined,
      department: department && department !== "All" ? department : undefined,
      search: search || undefined,
    },
    defaultFilename: `IntraSphere_Attendance_Report_${new Date().toISOString().slice(0, 10)}`,
  });
}

/**
 * HR Administrator: Export Leave Management Reports
 */
export async function exportLeaveReport({ format = "excel", startDate, endDate, department, status, leaveType }) {
  return downloadReport({
    endpoint: "/api/v1/reports/leave/export",
    format,
    params: {
      start_date: startDate || undefined,
      end_date: endDate || undefined,
      department: department && department !== "All" ? department : undefined,
      status: status && status !== "All" ? status : undefined,
      leave_type: leaveType && leaveType !== "All" ? leaveType : undefined,
    },
    defaultFilename: `IntraSphere_Leave_Report_${new Date().toISOString().slice(0, 10)}`,
  });
}

/**
 * Facility Manager: Export Resource Utilization & Occupancy Reports
 */
export async function exportResourceUtilizationReport({ format = "excel", startDate, endDate, floor, zone, resourceType }) {
  return downloadReport({
    endpoint: "/api/v1/facility/reports/export",
    format,
    params: {
      start_date: startDate || undefined,
      end_date: endDate || undefined,
      floor: floor !== undefined && floor !== "" ? floor : undefined,
      zone: zone && zone !== "All" ? zone : undefined,
      resource_type: resourceType && resourceType !== "all" ? resourceType : undefined,
    },
    defaultFilename: `IntraSphere_Resource_Utilization_Report_${new Date().toISOString().slice(0, 10)}`,
  });
}
